                .andExpect(status().isOk())
                .andExpect(jsonPath("$", hasSize(1)))
                .andExpect(jsonPath("$[0].readingId").value("r2"))
                .andExpect(jsonPath("$[0].anchorRevisionNo").value(1))
                .andExpect(jsonPath("$[0].anchorCumulativeMinutes").value(130));

        // 修订历史：初始登记为修订 1
