                            "锚点修订号与读数当前修订号不一致：期望 " + req.anchorRevisionNo()
                                    + "，当前 " + anchor.revisionNo());
                }
                Optional<MaintenanceRecord> last = repository.findLastMaintenance(equipmentId);
