                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"g-m1","expectedVersion":5,"readingId":"r-old",
                                 "anchorRevisionNo":1}
                                """))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("ANCHOR_BEFORE_COMMISSIONING"));
        // 锚点晚于服务端当前时间 → 422
