                                 "anchorRevisionNo":1}
                                """))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("ANCHOR_TIME_IN_FUTURE"));
        // 合法锚点（投用之后、现在之前）→ 201，冻结原因与新截止
