                .andExpect(jsonPath("$.calendarDue").value(false))
                .andExpect(jsonPath("$.newCalendarDeadline").value("2026-02-08T00:00:00Z"));

        // 未启用日历设备同样执行"不得晚于现在"门禁
        register("eq-gate2", 100000);
